// VARIABLE BINDINGS
const jobLifecycleAttribute = JobLifecycleAttribute?.value || "-";
const workOrderAttribute = WorkOrderAttribute?.value || "-";
const operatorAttribute = OperatorAttribute?.value || "-";
const timestamp = Timestamp?.value || helpers.now();
const assetPath = AssetPath || "-";
const alarmAttributePath = AlarmAttribute?.path || "-";
const jobLifecycleAttributePath = JobLifecycleAttribute?.path || "-";
const jobActivityAttributePath = JobActivityAttribute?.path || "-";
const workOrderAttributePath = WorkOrderAttribute?.path || "-";

// GET ACTIVE JOB LOAD EVENTS => Jasuindo.Taiyo1/Job/*/Lifecycle/Running
const openedEvents = await eventSys.get(`${ assetPath }/Job/${ workOrderAttribute }/Lifecycle/Running`, "*", "*", "open", {}, { limit: 1 });

// TEMPLATE EVENT PATH
const eventLifecyclePath = `${ assetPath }/Job/${ workOrderAttribute }/Lifecycle/`;
const eventActivityPath = `${assetPath}/Job/${workOrderAttribute}/Activity/*`;

helpers.log('event mulai:', jobLifecycleAttribute);

// CEK APAKAH LOAD/UNLOAD
if (!["load", "unload"].includes(String(jobLifecycleAttribute).toLowerCase())) {
  helpers.log('--- bukan load/unload');
  return;
}

helpers.log('--- terdeteksi load/unload');

// REJECT IF WORK ORDER IS EMPTY / "-" AND RAISE ALARM
if (workOrderAttribute === "-" || workOrderAttribute === "" || workOrderAttribute === null) {

  asset.set(alarmAttributePath, `!!!Work order is empty!!!`);
  asset.set(jobLifecycleAttributePath, `-`);

  msg.payload = "alarm: work order is empty";

  send(msg);

} else {

  asset.set(alarmAttributePath, `-`);

  // CREATE EVENT BASED ON LIFECYCLE
  if (jobLifecycleAttribute === "load") {

    if (openedEvents.length === 0) {

      const jobLifecycleContext = {
        operator: operatorAttribute,
        workOrder: workOrderAttribute,
      }

      await eventSys.open(
        `${eventLifecyclePath}Running`,
        timestamp,
        jobLifecycleContext,
        `${workOrderAttribute} loaded`,
        "info",
        {
          operator: operatorAttribute, workOrder: workOrderAttribute, lifecycle: "load", sourceAttribute: jobLifecycleAttributePath
        });

      msg.payload = "event opened";

      send(msg);

    }

  } else if (jobLifecycleAttribute === "unload") {

    if (openedEvents.length > 0) {

      await eventSys.close(`
        ${eventLifecyclePath}Running`,
        timestamp,
        `${workOrderAttribute} unloaded`,
        {
          operator: operatorAttribute, workOrder: workOrderAttribute, lifecycle: "unload", sourceAttribute: jobLifecycleAttributePath
        });

      await eventSys.close(
        `${eventActivityPath}`,
        timestamp,
        `${workOrderAttribute} unloaded`,
        {
          operator: operatorAttribute, workOrder: workOrderAttribute, lifecycle: "unload", closedPattern: eventActivityPath
        });

      asset.set(workOrderAttributePath, `-`);
      asset.set(jobLifecycleAttributePath, `-`);
      asset.set(jobActivityAttributePath, `-`);

      msg.payload = "event closed";

      send(msg);

    }

  }


}



return;

// VARIABLE BINDINGS
const jobActivityAttribute = JobActivityAttribute?.value || "-";
const jobActivityAttributePath = JobActivityAttribute?.path || "-";
