const operatorAttribute = OperatorAttribute?.value || "-";
const timestamp = Timestamp?.value || helpers.now();
const assetPath = AssetPath || "-";
const alarmAttributePath = AlarmAttribute?.path || "-";

// STOP jika reset / invalid (jangan bikin event)
if (jobActivityAttribute === "-" || jobActivityAttribute === "" || jobActivityAttribute === null) {
  send(msg);
  return;
}

// STOP jika wo not found (jangan bikin event)
if (workOrderAttribute === "-" || workOrderAttribute === "" || workOrderAttribute === null) {
  asset.set(alarmAttributePath, "!!!No Active Work Order!!!");
  send(msg);
  return;
}

const rawActivity = String(jobActivityAttribute).trim();
const activityLower = rawActivity.toLowerCase();

let activityType = "";
if (activityLower === "production") {
  activityType = "Production";
  asset.set(jobActivityCategoryAttributePath, activityType);
} else if (activityLower.startsWith("setup")) {
  activityType = "Setup";
  asset.set(jobActivityCategoryAttributePath, activityType);
} else if (activityLower.startsWith("idle")) {
  activityType = "Idle";
  asset.set(jobActivityCategoryAttributePath, activityType);
} else {
  asset.set(alarmAttributePath, `!!!Unknown activity type: ${rawActivity}!!!`);
  asset.set(jobActivityCategoryAttributePath, "-");
  send(msg);
  return;
}

