  asset.set(alarmAttributePath, `!!!Activity already open: ${rawActivity}!!!`);
  send(msg);
  return;
}

// Selalu enforce single active activity:
// sebelum open activity baru, tutup semua activity type lain
const setupPattern = `${basePath}/Setup/*`;
const productionPattern = `${basePath}/Production`;
const idlePattern = `${basePath}/Idle/*`;

if (activityType === "Production") {
  await eventSys.close(setupPattern, timestamp, "auto close by Production transition", { transitionTo: "Production", fromType: "Setup", workOrder: workOrderAttribute });
  await eventSys.close(idlePattern, timestamp, "auto close by Production transition", { transitionTo: "Production", fromType: "Idle", workOrder: workOrderAttribute });
} else if (activityType === "Setup") {
  asset.set(jobActivityCategoryAttributePath, "Setup");
  await eventSys.close(productionPattern, timestamp, "auto close by Setup transition", { transitionTo: "Setup", fromType: "Production", workOrder: workOrderAttribute });
  await eventSys.close(idlePattern, timestamp, "auto close by Setup transition", { transitionTo: "Setup", fromType: "Idle", workOrder: workOrderAttribute });
} else if (activityType === "Idle") {
  asset.set(jobActivityCategoryAttributePath, "Idle");
  await eventSys.close(productionPattern, timestamp, "auto close by Idle transition", { transitionTo: "Idle", fromType: "Production", workOrder: workOrderAttribute });
  await eventSys.close(setupPattern, timestamp, "auto close by Idle transition", { transitionTo: "Idle", fromType: "Setup", workOrder: workOrderAttribute });
}

asset.set(alarmAttributePath, "-");

