  eventPath,
  timestamp,
  activityContext,
  `activity ${rawActivity} created`,
  "info",
  { operator: operatorAttribute, workOrder: workOrderAttribute, activity: rawActivity, activityType, sourceAttribute: jobActivityAttributePath }
);

